const config = {
  "previewFeatures": [],
  "clientVersion": "7.2.0",
  "engineVersion": "0c8ef2ce45c83248ab3df073180d5eda9e8be7a3",
  "activeProvider": "postgresql",
  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n  output   = \"./generated\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  // Note: URL moved to prisma.config.ts for Prisma 7 compatibility\n  // For Prisma 6, this line is still required by the CLI\n}\n\nmodel User {\n  id        String   @id @default(cuid())\n  email     String   @unique\n  password  String\n  createdAt DateTime @default(now())\n  //updatedAt DateTime @updatedAt\n\n  // Profile information\n  profile       Profile?\n  pages         Page[]\n  analytics     Analytics[]\n  subscriptions Subscription[]\n  usage         UsageRecord[]\n  forms         Form[]\n\n  // New feature relations\n  campaigns              Campaign[]\n  repurposedContents     RepurposedContent[]\n  scheduledPosts         ScheduledPost[]\n  optimalTimeSlots       OptimalTimeSlot[]\n  schedulingPrefs        SchedulingPreferences?\n  leadMagnets            LeadMagnet[]\n  productTemplates       ProductTemplate[]\n  postTemplates          PostTemplate[]\n  campaignTemplates      CampaignTemplate[]\n  onboarding             UserOnboarding?\n  pageTemplates          PageTemplate[]\n  courses                Course[]\n  workflows              Workflow[]\n  funnels                Funnel[]\n  leads                  EmailSubscriber[]\n  // Coach platform relations\n  availabilityWindows    AvailabilityWindow[]\n  blackoutDates          BlackoutDate[]\n  bookings               Booking[]\n  stripeConnectedAccount StripeConnectedAccount?\n  creatorEarnings        CreatorEarning[]\n\n  // Enhancement features relations\n  templateCustomizations    TemplateCustomization[]\n  seoPerformance            SEOPerformance[]\n  contentOptimizations      ContentOptimization[]\n  templatePerformance       TemplatePerformance[]\n  abTestExperiments         ABTestExperiment[]\n  templatePurchasesAsBuyer  TemplatePurchase[]      @relation(\"TemplateBuyer\")\n  templatePurchasesAsSeller TemplatePurchase[]      @relation(\"TemplateSeller\")\n  templateReviews           TemplateReview[]\n  templateCreatorProfile    TemplateCreatorProfile?\n\n  @@map(\"users\")\n}\n\nmodel Profile {\n  id     String @id @default(cuid())\n  userId String @unique\n\n  username    String  @unique\n  displayName String\n  bio         String?\n  avatar      String?\n  theme       String  @default(\"default\")\n\n  // Contact information\n  phone    String?\n  website  String?\n  location String?\n  timezone String  @default(\"UTC\")\n\n  // Subscription and billing\n  plan               PlanEnum @default(FREE)\n  stripeCustomerId   String?\n  subscriptionId     String?\n  subscriptionStatus String?\n\n  // Coach features\n  isCoach         Boolean @default(false)\n  coachSlug       String? @unique\n  bookingEnabled  Boolean @default(false)\n  productsEnabled Boolean @default(false)\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@map(\"profiles\")\n}\n\nmodel Page {\n  id          String  @id @default(cuid())\n  userId      String\n  slug        String  @unique\n  title       String\n  description String?\n  isActive    Boolean @default(true)\n\n  // Domain configuration\n  customDomain                  String?\n  customDomainStatus            DomainStatus? @default(PENDING)\n  customDomainVerifiedAt        DateTime?\n  customDomainVerificationToken String?\n  subdomain                     String?       @unique\n\n  // SEO and metadata\n  metaTitle       String?\n  metaDescription String?\n  metaKeywords    String?\n  ogImage         String?\n\n  // Styling\n  backgroundColor String @default(\"#ffffff\")\n  textColor       String @default(\"#000000\")\n  buttonStyle     String @default(\"rounded\")\n  fontFamily      String @default(\"inter\")\n\n  // Enhanced styling (JSON for flexibility)\n  theme      Json? // Theme preset name and colors\n  typography Json? // Font settings, sizes, weights\n  layout     Json? // Container width, spacing, alignment\n  animations Json? // Animation preferences\n  customCss  String? @db.Text\n\n  // Analytics settings\n  googleAnalyticsId String?\n  facebookPixelId   String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  user   User        @relation(fields: [userId], references: [id], onDelete: Cascade)\n  header pageHeader?\n\n  blocks Block[]\n  clicks Click[]\n  forms  Form[]\n\n  // Enhancement features relations\n  templateCustomizations TemplateCustomization[]\n  seoPerformance         SEOPerformance[]\n  contentOptimizations   ContentOptimization[]\n  templatePerformance    TemplatePerformance[]\n  abTestExperiments      ABTestExperiment[]\n\n  @@map(\"pages\")\n}\n\nmodel pageHeader {\n  id     String @id @default(cuid())\n  pageId String @unique\n\n  data      Json     @default(\"{}\")\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  page Page @relation(fields: [pageId], references: [id], onDelete: Cascade)\n}\n\nmodel Block {\n  id       String    @id @default(cuid())\n  pageId   String\n  type     BlockType\n  position Int\n  isActive Boolean   @default(true)\n\n  // Basic properties\n  title       String\n  description String?\n  url         String?\n  imageUrl    String?\n\n  // Styling\n  backgroundColor String?\n  textColor       String?\n  borderRadius    Int     @default(8)\n\n  // Enhanced block styling (JSON for flexibility)\n  style Json? // { shadow, border, hoverEffect, layout, colors }\n\n  // Block-specific data (JSON for flexibility)\n  data Json @default(\"{}\")\n\n  // Scheduling\n  scheduledStart DateTime?\n  scheduledEnd   DateTime?\n\n  // A/B Testing\n  variantId String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  page                 Page                  @relation(fields: [pageId], references: [id], onDelete: Cascade)\n  clicks               Click[]\n  contentOptimizations ContentOptimization[]\n\n  // For extensibility: link to product, analytics, or form if needed\n  productId   String?\n  analyticsId String?\n  formId      String?\n\n  product   Product?   @relation(fields: [productId], references: [id])\n  analytics Analytics? @relation(fields: [analyticsId], references: [id])\n  form      Form?      @relation(fields: [formId], references: [id])\n\n  @@map(\"blocks\")\n}\n\n// Form model for email capture, waitlist, contact, etc.\nmodel Form {\n  id        String   @id @default(cuid())\n  userId    String\n  pageId    String\n  type      FormType\n  config    Json     @default(\"{}\")\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  user   User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n  page   Page    @relation(fields: [pageId], references: [id], onDelete: Cascade)\n  blocks Block[]\n\n  @@map(\"forms\")\n}\n\nenum FormType {\n  EMAIL_CAPTURE\n  WAITLIST\n  CONTACT\n  CUSTOM\n}\n\nmodel Click {\n  id      String  @id @default(cuid())\n  pageId  String\n  blockId String?\n\n  // Analytics data\n  ipAddress String\n  userAgent String\n  referer   String?\n  country   String?\n  city      String?\n  device    String?\n  browser   String?\n  os        String?\n\n  // UTM parameters\n  utmSource   String?\n  utmMedium   String?\n  utmCampaign String?\n  utmTerm     String?\n  utmContent  String?\n\n  timestamp DateTime @default(now())\n\n  page  Page   @relation(fields: [pageId], references: [id], onDelete: Cascade)\n  block Block? @relation(fields: [blockId], references: [id], onDelete: SetNull)\n\n  @@map(\"clicks\")\n}\n\n// Enhancement features relations for Block\n\nmodel Analytics {\n  id     String   @id @default(cuid())\n  userId String\n  date   DateTime\n\n  // Metrics\n  pageViews      Int   @default(0)\n  uniqueVisitors Int   @default(0)\n  totalClicks    Int   @default(0)\n  revenue        Float @default(0)\n\n  // Device breakdown\n  mobileViews  Int @default(0)\n  desktopViews Int @default(0)\n  tabletViews  Int @default(0)\n\n  // Traffic sources\n  directTraffic   Int @default(0)\n  socialTraffic   Int @default(0)\n  searchTraffic   Int @default(0)\n  referralTraffic Int @default(0)\n\n  user   User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n  blocks Block[]\n\n  @@unique([userId, date])\n  @@map(\"analytics\")\n}\n\nmodel Product {\n  id          String  @id @default(cuid())\n  userId      String\n  name        String\n  description String?\n  price       Float\n  currency    String  @default(\"USD\")\n\n  // Product type (PRODUCT or PACKAGE)\n  type ProductType @default(PRODUCT)\n\n  // Package fields (only used if type is PACKAGE)\n  packageProducts String[] // Array of product IDs included in this package\n\n  // Digital product files\n  fileUrl       String?\n  downloadLimit Int?\n\n  // Stripe integration\n  stripeProductId String?\n  stripePriceId   String?\n\n  isActive  Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  sales           Sale[]\n  blocks          Block[]\n  campaigns       Campaign[]\n  creatorEarnings CreatorEarning[]\n\n  @@map(\"products\")\n}\n\nenum ProductType {\n  PRODUCT\n  PACKAGE\n}\n\nmodel Sale {\n  id         String @id @default(cuid())\n  productId  String\n  buyerEmail String\n  amount     Float\n  currency   String @default(\"USD\")\n\n  // Payment processing\n  stripePaymentIntentId String?\n  status                String  @default(\"pending\")\n\n  createdAt DateTime @default(now())\n\n  product         Product          @relation(fields: [productId], references: [id])\n  creatorEarnings CreatorEarning[]\n\n  @@map(\"sales\")\n}\n\nmodel EmailSubscriber {\n  id              String    @id @default(cuid())\n  pageId          String\n  pageType        String\n  userId          String\n  email           String\n  name            String?\n  source          String? // Which block they subscribed from\n  phone           String?\n  company         String?\n  notes           String?\n  tags            String[] // For segmentation\n  pipelineStage   LeadStage @default(NEW)\n  lastContactedAt DateTime?\n  lastActivityAt  DateTime?\n  estimatedValue  Int?\n  isActive        Boolean   @default(true)\n  createdAt       DateTime  @default(now())\n  user            User      @relation(fields: [userId], references: [id])\n\n  @@unique([pageId, email])\n  @@index([userId])\n  @@index([userId, pipelineStage])\n  @@index([pipelineStage])\n  @@index([pageId, pageType])\n  @@map(\"email_subscribers\")\n}\n\nmodel ABTest {\n  id          String  @id @default(cuid())\n  pageId      String\n  name        String\n  description String?\n\n  // Test configuration\n  trafficSplit Float      @default(50) // Percentage for variant\n  status       TestStatus @default(DRAFT)\n\n  // Results\n  controlClicks Int @default(0)\n  controlViews  Int @default(0)\n  variantClicks Int @default(0)\n  variantViews  Int @default(0)\n\n  startDate DateTime?\n  endDate   DateTime?\n\n  createdAt DateTime @default(now())\n\n  @@map(\"ab_tests\")\n}\n\nmodel Integration {\n  id     String          @id @default(cuid())\n  userId String\n  type   IntegrationType\n  name   String\n\n  // Encrypted credentials and configuration\n  config Json\n\n  isActive  Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([userId, type])\n  @@map(\"integrations\")\n}\n\nmodel Webhook {\n  id     String         @id @default(cuid())\n  userId String\n  url    String\n  events WebhookEvent[]\n  secret String?\n\n  isActive  Boolean  @default(true)\n  createdAt DateTime @default(now())\n\n  @@map(\"webhooks\")\n}\n\nmodel AuditLog {\n  id         String  @id @default(cuid())\n  userId     String?\n  action     String\n  resource   String\n  resourceId String?\n\n  // Request details\n  ipAddress String?\n  userAgent String?\n\n  // Change details\n  oldValues Json?\n  newValues Json?\n\n  timestamp DateTime @default(now())\n\n  @@map(\"audit_logs\")\n}\n\nmodel ErrorLog {\n  id     String  @id @default(cuid())\n  userId String?\n\n  // Error details\n  message   String  @db.Text\n  stack     String? @db.Text\n  errorType String? // \"runtime\", \"boundary\", \"api\", \"validation\"\n\n  // App state capture\n  url       String?\n  pathname  String?\n  userAgent String?\n\n  // Component context\n  componentStack String? @db.Text\n\n  // User context (denormalized for quick access)\n  userEmail String?\n  userPlan  String?\n\n  // Additional context\n  context Json? // Flexible field for any extra data\n\n  // Status tracking\n  resolved   Boolean   @default(false)\n  resolvedAt DateTime?\n  resolvedBy String?\n  notes      String?   @db.Text\n\n  timestamp DateTime @default(now())\n\n  @@index([userId, timestamp])\n  @@index([resolved, timestamp])\n  @@index([errorType, timestamp])\n  @@map(\"error_logs\")\n}\n\n// ============================================\n// COACH PLATFORM: AVAILABILITY & BOOKINGS\n// ============================================\n\nmodel AvailabilityWindow {\n  id        String   @id @default(cuid())\n  userId    String\n  dayOfWeek Int // 0-6 (Sunday-Saturday)\n  startTime String // \"09:00\" format\n  endTime   String // \"17:00\" format\n  timezone  String   @default(\"UTC\")\n  isActive  Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId, dayOfWeek])\n  @@map(\"availability_windows\")\n}\n\nmodel BlackoutDate {\n  id        String   @id @default(cuid())\n  userId    String\n  startDate DateTime\n  endDate   DateTime\n  reason    String?\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId, startDate, endDate])\n  @@map(\"blackout_dates\")\n}\n\nmodel Booking {\n  id              String        @id @default(cuid())\n  userId          String // Coach\n  customerEmail   String\n  customerName    String?\n  startTime       DateTime\n  endTime         DateTime\n  duration        Int // minutes\n  price           Decimal?      @db.Decimal(10, 2)\n  currency        String        @default(\"USD\")\n  status          BookingStatus @default(PENDING)\n  notes           String?       @db.Text\n  stripePaymentId String?\n  createdAt       DateTime      @default(now())\n  updatedAt       DateTime      @updatedAt\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId, startTime])\n  @@index([customerEmail])\n  @@index([status])\n  @@map(\"bookings\")\n}\n\n// Subscription plans\nmodel Plan {\n  id          String   @id @default(cuid())\n  name        String   @unique // e.g., \"Free\", \"Pro\", \"Enterprise\"\n  description String?\n  planEnum    PlanEnum\n  price       Decimal  @db.Decimal(10, 2)\n  interval    String // \"month\", \"year\"\n  isActive    Boolean  @default(true)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n  priceId     String?\n\n  features      PlanFeature[]\n  subscriptions Subscription[]\n\n  @@index([name])\n}\n\n// Features available in the system\nmodel Feature {\n  id          String   @id @default(cuid())\n  name        String   @unique // e.g., \"api_calls\", \"storage\", \"users\"\n  description String?\n  type        String // \"boolean\", \"quota\", \"rate_limit\"\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  planFeatures PlanFeature[]\n  usageRecords UsageRecord[]\n\n  @@index([name])\n}\n\n// Junction table: Plan features with limits\nmodel PlanFeature {\n  id        String @id @default(cuid())\n  planId    String\n  featureId String\n\n  // For boolean features (enabled/disabled)\n  enabled Boolean @default(true)\n\n  // For quota-based features (e.g., 1000 API calls/month)\n  limit Int? // null = unlimited\n\n  // For rate limiting (e.g., 100 requests per minute)\n  rateLimit  Int? // requests allowed\n  ratePeriod String? // \"minute\", \"hour\", \"day\"\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  plan    Plan    @relation(fields: [planId], references: [id], onDelete: Cascade)\n  feature Feature @relation(fields: [featureId], references: [id], onDelete: Cascade)\n\n  @@unique([planId, featureId])\n  @@index([planId])\n  @@index([featureId])\n}\n\n// User subscriptions\nmodel Subscription {\n  id     String @id @default(cuid())\n  userId String @unique\n  planId String\n\n  status             String // \"active\", \"canceled\", \"past_due\", \"trialing\"\n  currentPeriodStart DateTime\n  currentPeriodEnd   DateTime\n  cancelAtPeriodEnd  Boolean  @default(false)\n\n  // Payment provider info\n  stripeSubscriptionId String? @unique\n  stripeCustomerId     String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n  plan Plan @relation(fields: [planId], references: [id])\n\n  @@index([userId])\n  @@index([planId])\n  @@index([status])\n}\n\n// ============================================\n// STRIPE CONNECT: CREATOR ACCOUNTS & EARNINGS\n// ============================================\n\nmodel StripeConnectedAccount {\n  id        String @id @default(cuid())\n  userId    String @unique\n  // Stripe account ID, e.g., acct_123\n  accountId String @unique\n\n  // Capability status mirrors Stripe capabilities\n  chargesEnabled   Boolean @default(false)\n  payoutsEnabled   Boolean @default(false)\n  detailsSubmitted Boolean @default(false)\n\n  // Account information\n  country         String?\n  defaultCurrency String? @default(\"USD\")\n  businessType    String?\n\n  // Platform fee defaults (% as decimal, e.g. 10 = 10%)\n  applicationFeePercent Int? // If null, use platform default\n\n  // Onboarding state\n  requirements Json?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@map(\"stripe_connected_accounts\")\n}\n\nmodel CreatorEarning {\n  id        String  @id @default(cuid())\n  userId    String\n  // Foreign keys\n  productId String?\n  saleId    String?\n  bookingId String?\n\n  // Amounts\n  grossAmount     Decimal @db.Decimal(10, 2)\n  stripeFees      Decimal @default(0) @db.Decimal(10, 2)\n  applicationFees Decimal @default(0) @db.Decimal(10, 2)\n  netAmount       Decimal @db.Decimal(10, 2)\n  currency        String  @default(\"USD\")\n\n  // Stripe references\n  chargeId           String?\n  transferId         String?\n  payoutId           String?\n  connectedAccountId String? // acct_...\n\n  // Status\n  status      String    @default(\"pending\") // pending | available | paid | reversed\n  availableAt DateTime?\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  user    User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  product Product? @relation(fields: [productId], references: [id])\n  sale    Sale?    @relation(fields: [saleId], references: [id])\n\n  @@index([userId, status])\n  @@index([connectedAccountId, status])\n  @@map(\"creator_earnings\")\n}\n\n// Track feature usage for rate limiting and quotas\nmodel UsageRecord {\n  id        String @id @default(cuid())\n  userId    String\n  featureId String\n\n  count       Int      @default(1)\n  periodStart DateTime\n  periodEnd   DateTime\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  user    User    @relation(fields: [userId], references: [id], onDelete: Cascade)\n  feature Feature @relation(fields: [featureId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, featureId, periodStart])\n  @@index([userId, featureId, periodStart])\n  @@index([periodEnd])\n}\n\nenum PlanEnum {\n  FREE\n  CREATOR\n  PRO\n  BUSINESS\n  SUPER_ADMIN\n}\n\nenum DomainStatus {\n  PENDING\n  VERIFIED\n  FAILED\n}\n\nenum BookingStatus {\n  PENDING\n  CONFIRMED\n  COMPLETED\n  CANCELLED\n  NO_SHOW\n}\n\nenum BlockType {\n  LINK\n  DEEP_LINK\n  PRODUCT\n  EMAIL_CAPTURE\n  IMAGE_GALLERY\n  MUSIC_PLAYER\n  VIDEO_EMBED\n  BOOKING_CALENDAR\n  TIP_JAR\n  SOCIAL_FEED\n  AMA_BLOCK\n  GATED_CONTENT\n  RSS_FEED\n  PORTFOLIO\n  CONTACT_FORM\n  DIVIDER\n  TEXT_BLOCK\n  ANALYTICS\n  PROMO\n  DISCOUNT\n  SOCIAL_SHARE\n  WAITLIST\n  NEWSLETTER\n  CUSTOM\n  COURSE\n  FUNNEL\n  QUIZ\n  SOCIAL_PROOF\n  SAAS_APP\n}\n\nenum LeadStage {\n  NEW\n  CONTACTED\n  QUALIFIED\n  PROPOSAL\n  NEGOTIATION\n  WON\n  LOST\n}\n\nenum TestStatus {\n  DRAFT\n  RUNNING\n  PAUSED\n  COMPLETED\n}\n\nenum IntegrationType {\n  STRIPE\n  PAYPAL\n  MAILCHIMP\n  CONVERTKIT\n  CALENDLY\n  SHOPIFY\n  GUMROAD\n  GOOGLE_ANALYTICS\n  FACEBOOK_PIXEL\n  ZAPIER\n}\n\nenum WebhookEvent {\n  PAGE_VIEW\n  BLOCK_CLICK\n  EMAIL_SIGNUP\n  PRODUCT_SALE\n  TIP_RECEIVED\n}\n\n// ============================================\n// FEATURE #1: AUTO-CAMPAIGN GENERATOR\n// ============================================\n\nmodel Campaign {\n  id        String         @id @default(cuid())\n  createdAt DateTime       @default(now())\n  updatedAt DateTime       @updatedAt\n  userId    String\n  status    CampaignStatus\n\n  // Source content\n  productId     String?\n  blockId       String?\n  customContent Json?\n\n  // Generated assets\n  assets CampaignAsset[]\n\n  // Campaign metadata\n  name           String\n  goal           String?\n  targetAudience String?\n\n  // Performance tracking\n  analyticsId String?\n\n  user    User     @relation(fields: [userId], references: [id])\n  product Product? @relation(fields: [productId], references: [id])\n\n  @@index([userId, status])\n  @@map(\"campaigns\")\n}\n\nenum CampaignStatus {\n  DRAFT\n  GENERATING\n  READY\n  FAILED\n}\n\nmodel CampaignAsset {\n  id        String   @id @default(cuid())\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  campaignId String\n  campaign   Campaign @relation(fields: [campaignId], references: [id], onDelete: Cascade)\n\n  type     AssetType\n  platform Platform?\n\n  // Content\n  content  String  @db.Text\n  mediaUrl String?\n\n  // Scheduling\n  scheduledAt DateTime?\n  publishedAt DateTime?\n  status      AssetStatus\n\n  // Performance\n  views       Int @default(0)\n  clicks      Int @default(0)\n  conversions Int @default(0)\n\n  @@index([campaignId])\n  @@map(\"campaign_assets\")\n}\n\nenum AssetType {\n  SOCIAL_POST\n  EMAIL\n  PAGE_VARIANT\n  IMAGE\n  VIDEO_CLIP\n}\n\nenum Platform {\n  TWITTER\n  INSTAGRAM\n  FACEBOOK\n  LINKEDIN\n  TIKTOK\n  EMAIL\n  LINK_IN_BIO\n}\n\nenum AssetStatus {\n  DRAFT\n  APPROVED\n  SCHEDULED\n  PUBLISHED\n  FAILED\n}\n\n// ============================================\n// FEATURE #3: CONTENT REPURPOSING STUDIO\n// ============================================\n\nmodel RepurposedContent {\n  id        String   @id @default(cuid())\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n  userId    String\n\n  // Source content\n  sourceUrl   String\n  sourceType  SourceType\n  sourceTitle String?\n  sourceMeta  Json?\n\n  // Extracted data\n  transcript String? @db.Text\n  keyPoints  Json?\n  duration   Int?\n\n  // Processing status\n  status RepurposeStatus\n  error  String?\n\n  // Generated assets\n  assets RepurposedAsset[]\n\n  // Settings\n  brandColors Json?\n  brandLogo   String?\n\n  user User @relation(fields: [userId], references: [id])\n\n  @@index([userId, status])\n  @@map(\"repurposed_contents\")\n}\n\nenum SourceType {\n  YOUTUBE\n  TIKTOK\n  INSTAGRAM\n  VIMEO\n  BLOG\n  MEDIUM\n  SUBSTACK\n  LINKEDIN_ARTICLE\n  TWITTER_THREAD\n  PODCAST_RSS\n  PODCAST_MP3\n  SPOTIFY\n  APPLE_PODCASTS\n  MANUAL_TEXT\n}\n\nenum RepurposeStatus {\n  ANALYZING\n  EXTRACTING\n  GENERATING\n  READY\n  FAILED\n}\n\nmodel RepurposedAsset {\n  id        String   @id @default(cuid())\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  repurposedContentId String\n  repurposedContent   RepurposedContent @relation(fields: [repurposedContentId], references: [id], onDelete: Cascade)\n\n  type     RepurposeAssetType\n  platform Platform?\n\n  // Content\n  content  String? @db.Text\n  mediaUrl String?\n  metadata Json?\n\n  // Publishing\n  published   Boolean   @default(false)\n  publishedAt DateTime?\n  blockId     String?\n\n  // User edits\n  edited          Boolean @default(false)\n  originalContent String? @db.Text\n\n  @@index([repurposedContentId])\n  @@map(\"repurposed_assets\")\n}\n\nenum RepurposeAssetType {\n  TWITTER_THREAD\n  LINKEDIN_POST\n  INSTAGRAM_CAPTION\n  FACEBOOK_POST\n  EMAIL_NEWSLETTER\n  BLOG_SUMMARY\n  QUOTE_GRAPHIC\n  CAROUSEL_SLIDE\n  INFOGRAPHIC\n  VIDEO_CLIP\n  THUMBNAIL\n}\n\n// ============================================\n// FEATURE #6: SMART SCHEDULING ENGINE\n// ============================================\n\nmodel ScheduledPost {\n  id        String   @id @default(cuid())\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n  userId    String\n\n  // Content4e \n  content   String   @db.Text\n  mediaUrls String[]\n\n  // Platform\n  platform     Platform\n  platformType PostType\n\n  // Scheduling\n  scheduledFor DateTime\n  timezone     String   @default(\"UTC\")\n  priority     Int      @default(0)\n\n  // Publishing\n  status      ScheduleStatus\n  publishedAt DateTime?\n  externalId  String?\n  externalUrl String?\n\n  // Mode\n  autoPost Boolean @default(false)\n\n  // Source tracking\n  campaignAssetId   String?\n  repurposedAssetId String?\n\n  // Error handling\n  attempts  Int     @default(0)\n  lastError String?\n\n  // Performance\n  views    Int?\n  clicks   Int?\n  likes    Int?\n  comments Int?\n  shares   Int?\n\n  user User @relation(fields: [userId], references: [id])\n\n  @@index([userId, scheduledFor, status])\n  @@index([scheduledFor, status])\n  @@map(\"scheduled_posts\")\n}\n\nenum ScheduleStatus {\n  PENDING\n  PROCESSING\n  PUBLISHED\n  FAILED\n  CANCELLED\n}\n\nenum PostType {\n  FEED_POST\n  STORY\n  REEL\n  TWEET\n  THREAD\n  LINKEDIN_POST\n  FACEBOOK_POST\n}\n\nmodel OptimalTimeSlot {\n  id        String   @id @default(cuid())\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n  userId    String\n\n  // Time slot\n  dayOfWeek Int\n  hourOfDay Int\n\n  // Platform-specific\n  platform Platform?\n\n  // Metrics\n  avgEngagementRate Decimal @db.Decimal(5, 2)\n  totalViews        Int     @default(0)\n  totalClicks       Int     @default(0)\n  sampleSize        Int     @default(0)\n\n  // Confidence\n  confidence Decimal @db.Decimal(5, 2)\n\n  // Ranking\n  rank Int\n\n  // Analysis period\n  analyzedFrom DateTime\n  analyzedTo   DateTime\n\n  user User @relation(fields: [userId], references: [id])\n\n  @@unique([userId, platform, dayOfWeek, hourOfDay])\n  @@index([userId, rank])\n  @@map(\"optimal_time_slots\")\n}\n\nmodel SchedulingPreferences {\n  id     String @id @default(cuid())\n  userId String @unique\n\n  // Default settings\n  defaultMode SchedulingMode @default(SUGGESTION)\n  timezone    String         @default(\"America/New_York\")\n\n  // Posting constraints\n  noPostBefore Int   @default(8)\n  noPostAfter  Int   @default(22)\n  excludedDays Int[]\n\n  // Platform preferences\n  preferredPlatforms Platform[]\n\n  // Spread settings\n  minHoursBetween Int @default(4)\n  maxPostsPerDay  Int @default(5)\n\n  // Analysis\n  dataRequirement Int @default(30)\n\n  user User @relation(fields: [userId], references: [id])\n\n  @@map(\"scheduling_preferences\")\n}\n\nenum SchedulingMode {\n  SUGGESTION\n  AUTO_POST\n  HYBRID\n}\n\nenum TemplateType {\n  BIO_ONLY\n  FULL_PAGE\n}\n\n// ============================================\n// FEATURE #7: LEAD MAGNET AUTOMATION SUITE\n// ============================================\n\nmodel LeadMagnet {\n  id        String   @id @default(cuid())\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n  userId    String\n\n  // Magnet details\n  name        String\n  slug        String?    @unique\n  description String?    @db.Text\n  type        MagnetType\n\n  // Asset storage\n  fileUrl  String?\n  fileSize Int?\n  fileName String?\n  mimeType String?\n\n  // Multi-asset courses\n  assets LeadMagnetAsset[]\n\n  // Opt-in copy\n  headline    String\n  subheadline String?\n  benefits    String[]\n\n  // Branding\n  coverImageUrl String?\n  brandColors   Json?\n\n  // Delivery settings\n  deliveryMethod DeliveryMethod\n  deliveryDelay  Int            @default(0)\n\n  // Email drip settings\n  dripEnabled  Boolean @default(false)\n  dripSchedule Json?\n\n  // Email template\n  emailSubject String?\n  emailBody    String? @db.Text\n\n  // Performance tracking\n  views          Int      @default(0)\n  optIns         Int      @default(0)\n  downloads      Int      @default(0)\n  conversionRate Decimal? @db.Decimal(5, 2)\n\n  // Gating\n  emailCaptureBlockId String?\n\n  // Status\n  status      MagnetStatus @default(DRAFT)\n  publishedAt DateTime?\n\n  user       User                 @relation(fields: [userId], references: [id])\n  deliveries LeadMagnetDelivery[]\n\n  @@index([userId, status])\n  @@map(\"lead_magnets\")\n}\n\nenum MagnetType {\n  PDF\n  EBOOK\n  TEMPLATE\n  CHECKLIST\n  WORKBOOK\n  VIDEO\n  VIDEO_COURSE\n  AUDIO\n  SPREADSHEET\n  ZIP_BUNDLE\n  CUSTOM\n}\n\nenum DeliveryMethod {\n  INSTANT_DOWNLOAD\n  EMAIL_DELIVERY\n  GATED_ACCESS\n  HYBRID\n  DRIP_COURSE\n}\n\nenum MagnetStatus {\n  DRAFT\n  ACTIVE\n  PAUSED\n  ARCHIVED\n}\n\nmodel LeadMagnetAsset {\n  id           String     @id @default(cuid())\n  createdAt    DateTime   @default(now())\n  leadMagnetId String\n  leadMagnet   LeadMagnet @relation(fields: [leadMagnetId], references: [id], onDelete: Cascade)\n\n  // Asset details\n  name        String\n  description String?\n  fileUrl     String\n  fileSize    Int\n  mimeType    String\n\n  // Ordering\n  order Int @default(0)\n\n  // Drip schedule\n  dripDay Int?\n\n  @@index([leadMagnetId, order])\n  @@map(\"lead_magnet_assets\")\n}\n\nmodel LeadMagnetDelivery {\n  id        String   @id @default(cuid())\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  leadMagnetId String\n  leadMagnet   LeadMagnet @relation(fields: [leadMagnetId], references: [id])\n\n  // Recipient\n  email             String\n  name              String?\n  emailSubscriberId String?\n\n  // Delivery tracking\n  delivered       Boolean   @default(false)\n  deliveredAt     DateTime?\n  downloadedCount Int       @default(0)\n  lastDownloadAt  DateTime?\n\n  // Email tracking\n  emailSent        Boolean @default(false)\n  emailOpened      Boolean @default(false)\n  emailClickedLink Boolean @default(false)\n\n  // Drip course tracking\n  currentAssetIndex Int      @default(0)\n  completedAssets   String[]\n\n  // Unique delivery token\n  deliveryToken  String    @unique\n  tokenExpiresAt DateTime?\n\n  // Attribution\n  source   String?\n  medium   String?\n  campaign String?\n\n  @@index([leadMagnetId, email])\n  @@index([deliveryToken])\n  @@map(\"lead_magnet_deliveries\")\n}\n\nmodel LeadMagnetTemplate {\n  id        String   @id @default(cuid())\n  createdAt DateTime @default(now())\n\n  // Template details\n  name        String\n  description String           @db.Text\n  category    TemplateCategory\n  type        MagnetType\n\n  // Preview\n  thumbnailUrl String\n  previewUrl   String?\n\n  // Template file\n  templateUrl String\n\n  // Popularity\n  useCount Int     @default(0)\n  featured Boolean @default(false)\n\n  // Sample content\n  samplePrompt String? @db.Text\n\n  @@map(\"lead_magnet_templates\")\n}\n\nenum TemplateCategory {\n  CHECKLIST\n  WORKBOOK\n  CHEAT_SHEET\n  RESOURCE_LIST\n  SWIPE_FILE\n  GUIDE\n  PLANNER\n  TRACKER\n  EBOOK\n  MINI_COURSE\n}\n\n// ============================================\n// TEMPLATES SYSTEM\n// ============================================\n\nmodel ProductTemplate {\n  id        String   @id @default(cuid())\n  createdAt DateTime @default(now())\n  userId    String?\n\n  // Template details\n  name          String\n  description   String?\n  price         Float\n  currency      String  @default(\"USD\")\n  downloadLimit Int?\n\n  // Category\n  category String // \"Course\", \"Ebook\", \"Template\", \"Digital Art\", etc.\n\n  // Preview\n  thumbnailUrl String?\n\n  // Popularity\n  useCount Int     @default(0)\n  featured Boolean @default(false)\n  isPublic Boolean @default(false)\n\n  user User? @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId, category])\n  @@index([featured, useCount])\n  @@map(\"product_templates\")\n}\n\nmodel PostTemplate {\n  id        String   @id @default(cuid())\n  createdAt DateTime @default(now())\n  userId    String?\n\n  // Template details\n  name        String\n  description String?\n  content     String   @db.Text\n  platform    Platform\n  postType    PostType\n  mediaUrls   String[]\n\n  // Category\n  category String // \"Promotional\", \"Educational\", \"Engagement\", etc.\n\n  // Popularity\n  useCount Int     @default(0)\n  featured Boolean @default(false)\n  isPublic Boolean @default(false)\n\n  user User? @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId, platform])\n  @@index([featured, useCount])\n  @@map(\"post_templates\")\n}\n\nmodel CampaignTemplate {\n  id        String   @id @default(cuid())\n  createdAt DateTime @default(now())\n  userId    String?\n\n  // Template details\n  name           String\n  description    String?\n  goal           String?\n  targetAudience String?\n  platforms      Platform[]\n  tone           String?\n\n  // Category\n  category String // \"Product Launch\", \"Lead Generation\", \"Awareness\", etc.\n\n  // Popularity\n  useCount Int     @default(0)\n  featured Boolean @default(false)\n  isPublic Boolean @default(false)\n\n  user User? @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId, category])\n  @@index([featured, useCount])\n  @@map(\"campaign_templates\")\n}\n\nmodel PageTemplate {\n  id        String   @id @default(cuid())\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n  userId    String?\n\n  // Template metadata\n  name        String\n  description String?  @db.Text\n  category    String\n  industry    String? // Industry-specific classification\n  tags        String[]\n\n  // Template type\n  templateType TemplateType\n\n  // Template data storage\n  headerData Json\n  blocksData Json\n  theme      Json? // Theme configuration (colors, fonts, spacing)\n\n  // Preview assets\n  thumbnailUrl String\n  previewUrl   String?\n\n  // Popularity tracking\n  useCount Int     @default(0)\n  rating   Float?  @default(0)\n  featured Boolean @default(false)\n  isPublic Boolean @default(false)\n\n  // Marketplace fields\n  price          Decimal? @db.Decimal(10, 2)\n  currency       String   @default(\"USD\")\n  isPaid         Boolean  @default(false)\n  commissionRate Decimal? @db.Decimal(5, 2)\n  totalRevenue   Decimal  @default(0) @db.Decimal(10, 2)\n  totalSales     Int      @default(0)\n  licenseType    String   @default(\"free\") // free, paid, premium\n\n  // Relations\n  user           User?                   @relation(fields: [userId], references: [id], onDelete: Cascade)\n  customizations TemplateCustomization[]\n  performance    TemplatePerformance[]\n  purchases      TemplatePurchase[]\n  reviews        TemplateReview[]\n  abTestsA       ABTestExperiment[]      @relation(\"TemplateA\")\n  abTestsB       ABTestExperiment[]      @relation(\"TemplateB\")\n  abTestsWinner  ABTestExperiment[]      @relation(\"WinnerTemplate\")\n\n  @@index([userId, category])\n  @@index([category, featured])\n  @@index([industry])\n  @@index([useCount])\n  @@index([featured, useCount])\n  @@index([category, templateType])\n  @@map(\"page_templates\")\n}\n\n// ============================================\n// MICRO-COURSE SYSTEM\n// ============================================\n\nmodel Course {\n  id        String   @id @default(cuid())\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n  userId    String\n\n  // Course details\n  title       String\n  description String?  @db.Text\n  slug        String   @unique\n  category    String?\n  tags        String[]\n\n  // Course metadata\n  level         CourseLevel @default(BEGINNER)\n  estimatedTime Int? // in minutes\n  language      String      @default(\"en\")\n\n  // Media\n  coverImageUrl String?\n  promoVideoUrl String?\n\n  // Access control\n  accessType CourseAccessType @default(FREE)\n  price      Decimal?         @db.Decimal(10, 2)\n  currency   String           @default(\"USD\")\n\n  // Lead magnet settings\n  leadMagnetId  String?\n  isLeadMagnet  Boolean @default(false)\n  requiresEmail Boolean @default(false)\n\n  // Publishing\n  status      CourseStatus @default(DRAFT)\n  publishedAt DateTime?\n\n  // Analytics\n  enrollmentCount Int      @default(0)\n  completionRate  Decimal? @db.Decimal(5, 2)\n  averageRating   Decimal? @db.Decimal(3, 2)\n\n  // SEO\n  metaTitle       String?\n  metaDescription String?\n\n  // Relations\n  user        User               @relation(fields: [userId], references: [id], onDelete: Cascade)\n  lessons     CourseLesson[]\n  enrollments CourseEnrollment[]\n  reviews     CourseReview[]\n\n  @@index([userId, status])\n  @@index([slug])\n  @@index([category, status])\n  @@map(\"courses\")\n}\n\nenum CourseLevel {\n  BEGINNER\n  INTERMEDIATE\n  ADVANCED\n  ALL_LEVELS\n}\n\nenum CourseAccessType {\n  FREE\n  PAID\n  EMAIL_GATE\n  MEMBERSHIP\n}\n\nenum CourseStatus {\n  DRAFT\n  PUBLISHED\n  ARCHIVED\n}\n\nmodel CourseLesson {\n  id        String   @id @default(cuid())\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n  courseId  String\n\n  // Lesson details\n  title       String\n  description String? @db.Text\n  order       Int\n\n  // Content\n  contentType LessonContentType\n  content     String?           @db.Text // For text/markdown\n  videoUrl    String? // For video\n  videoLength Int? // in seconds\n  audioUrl    String? // For audio\n\n  // Additional resources\n  resources LessonResource[]\n\n  // Quiz/Assessment\n  hasQuiz  Boolean @default(false)\n  quizData Json?\n\n  // Drip settings\n  dripDay         Int? // Release after N days of enrollment\n  dripAfterLesson String? // Release after completing specific lesson\n\n  // Analytics\n  viewCount      Int      @default(0)\n  completionRate Decimal? @db.Decimal(5, 2)\n  avgTimeSpent   Int? // in seconds\n\n  // Publishing\n  isPublished Boolean @default(true)\n  isFree      Boolean @default(false) // Preview lesson\n\n  // Relations\n  course   Course                 @relation(fields: [courseId], references: [id], onDelete: Cascade)\n  progress CourseLessonProgress[]\n\n  @@index([courseId, order])\n  @@map(\"course_lessons\")\n}\n\nenum LessonContentType {\n  TEXT\n  VIDEO\n  AUDIO\n  EMBED\n  PDF\n  MIXED\n}\n\nmodel LessonResource {\n  id        String   @id @default(cuid())\n  createdAt DateTime @default(now())\n  lessonId  String\n\n  // Resource details\n  name        String\n  description String?\n  type        ResourceType\n  url         String\n  fileSize    Int?\n\n  // Download tracking\n  downloadCount Int @default(0)\n\n  // Relations\n  lesson CourseLesson @relation(fields: [lessonId], references: [id], onDelete: Cascade)\n\n  @@index([lessonId])\n  @@map(\"lesson_resources\")\n}\n\nenum ResourceType {\n  PDF\n  DOCUMENT\n  SPREADSHEET\n  VIDEO\n  AUDIO\n  IMAGE\n  ARCHIVE\n  LINK\n  OTHER\n}\n\nmodel CourseEnrollment {\n  id        String   @id @default(cuid())\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n  courseId  String\n  userId    String?\n\n  // Enrollment details\n  email            String\n  name             String?\n  enrollmentSource String? // Where they enrolled from\n\n  // Payment (for paid courses)\n  paymentStatus   String? // \"pending\", \"completed\", \"failed\"\n  paymentAmount   Decimal? @db.Decimal(10, 2)\n  stripePaymentId String?\n\n  // Progress tracking\n  currentLessonId    String?\n  progressPercentage Int       @default(0)\n  completedAt        DateTime?\n\n  // Certificate\n  certificateIssued   Boolean   @default(false)\n  certificateUrl      String?\n  certificateIssuedAt DateTime?\n\n  // Access\n  expiresAt            DateTime?\n  accessRevoked        Boolean   @default(false)\n  accessToken          String?   @unique\n  accessTokenExpiresAt DateTime?\n\n  // Engagement\n  lastAccessedAt DateTime?\n  totalTimeSpent Int       @default(0) // in seconds\n\n  // Relations\n  course         Course                 @relation(fields: [courseId], references: [id], onDelete: Cascade)\n  lessonProgress CourseLessonProgress[]\n\n  @@unique([courseId, email])\n  @@index([courseId, progressPercentage])\n  @@index([accessToken])\n  @@index([email])\n  @@map(\"course_enrollments\")\n}\n\nmodel CourseLessonProgress {\n  id           String   @id @default(cuid())\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n  enrollmentId String\n  lessonId     String\n\n  // Progress\n  status          LessonProgressStatus @default(NOT_STARTED)\n  progressPercent Int                  @default(0)\n  completedAt     DateTime?\n\n  // Engagement\n  timeSpent    Int  @default(0) // in seconds\n  lastPosition Int? // Video/audio position in seconds\n  viewCount    Int  @default(0)\n\n  // Quiz results\n  quizAttempts Int       @default(0)\n  quizScore    Decimal?  @db.Decimal(5, 2)\n  quizPassedAt DateTime?\n\n  // Notes\n  notes String? @db.Text\n\n  // Relations\n  enrollment CourseEnrollment @relation(fields: [enrollmentId], references: [id], onDelete: Cascade)\n  lesson     CourseLesson     @relation(fields: [lessonId], references: [id], onDelete: Cascade)\n\n  @@unique([enrollmentId, lessonId])\n  @@index([enrollmentId, status])\n  @@map(\"course_lesson_progress\")\n}\n\nenum LessonProgressStatus {\n  NOT_STARTED\n  IN_PROGRESS\n  COMPLETED\n}\n\nmodel CourseReview {\n  id        String   @id @default(cuid())\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n  courseId  String\n\n  // Reviewer\n  email String\n  name  String?\n\n  // Review\n  rating  Int // 1-5\n  comment String? @db.Text\n\n  // Moderation\n  approved Boolean @default(false)\n  featured Boolean @default(false)\n\n  // Relations\n  course Course @relation(fields: [courseId], references: [id], onDelete: Cascade)\n\n  @@index([courseId, approved])\n  @@map(\"course_reviews\")\n}\n\n// ============================================\n// AUTOMATION WORKFLOW SYSTEM\n// ============================================\n\nmodel Workflow {\n  id        String   @id @default(cuid())\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n  userId    String\n\n  // Workflow details\n  name        String\n  description String? @db.Text\n\n  // Visual canvas data (node positions, connections)\n  canvasData Json?\n\n  // Status\n  status    WorkflowStatus @default(DRAFT)\n  lastRunAt DateTime?\n\n  // Performance\n  totalRuns      Int @default(0)\n  successfulRuns Int @default(0)\n  failedRuns     Int @default(0)\n\n  // Settings\n  enabled Boolean @default(true)\n\n  // Relations\n  user       User                @relation(fields: [userId], references: [id], onDelete: Cascade)\n  trigger    WorkflowTrigger?\n  steps      WorkflowStep[]\n  executions WorkflowExecution[]\n\n  @@index([userId, status])\n  @@index([userId, enabled])\n  @@map(\"workflows\")\n}\n\nenum WorkflowStatus {\n  DRAFT\n  ACTIVE\n  PAUSED\n  ARCHIVED\n}\n\nmodel WorkflowTrigger {\n  id         String   @id @default(cuid())\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n  workflowId String   @unique\n\n  // Trigger configuration\n  triggerType TriggerType\n  config      Json // Stores type-specific configuration\n\n  // Filter conditions\n  filters Json?\n\n  // Relations\n  workflow Workflow @relation(fields: [workflowId], references: [id], onDelete: Cascade)\n\n  @@index([triggerType])\n  @@map(\"workflow_triggers\")\n}\n\nenum TriggerType {\n  NEW_SUBSCRIBER // When someone subscribes to email list\n  NEW_COURSE_ENROLLMENT // When someone enrolls in course\n  LESSON_COMPLETED // When lesson is completed\n  COURSE_COMPLETED // When entire course is completed\n  FORM_SUBMITTED // When a form is submitted\n  PRODUCT_PURCHASED // When product is purchased\n  PAGE_VIEWED // When page is viewed\n  BLOCK_CLICKED // When specific block is clicked\n  TAG_ADDED // When tag is added to subscriber\n  TAG_REMOVED // When tag is removed\n  SCHEDULE // Time-based trigger\n  WEBHOOK // External webhook trigger\n  MANUAL // Manually triggered\n}\n\nmodel WorkflowStep {\n  id         String   @id @default(cuid())\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n  workflowId String\n\n  // Step details\n  name  String\n  type  StepType\n  order Int\n\n  // Action/Condition configuration\n  config Json\n\n  // Conditional branching\n  parentStepId String? // For conditional branches\n  condition    Json? // If this is a conditional branch\n\n  // Delay settings\n  delayAmount Int? // Amount of time\n  delayUnit   DelayUnit?\n\n  // Relations\n  workflow Workflow          @relation(fields: [workflowId], references: [id], onDelete: Cascade)\n  logs     WorkflowStepLog[]\n\n  @@index([workflowId, order])\n  @@map(\"workflow_steps\")\n}\n\nenum StepType {\n  // Actions\n  SEND_EMAIL\n  ADD_TAG\n  REMOVE_TAG\n  SUBSCRIBE_TO_LIST\n  UNSUBSCRIBE_FROM_LIST\n  ENROLL_IN_COURSE\n  GRANT_ACCESS\n  REVOKE_ACCESS\n  SEND_SMS\n  SEND_WEBHOOK\n  CREATE_TASK\n  UPDATE_SUBSCRIBER\n  SEND_NOTIFICATION\n\n  // Control flow\n  WAIT\n  DELAY\n  CONDITION\n  BRANCH\n  SPLIT_TEST\n\n  // Integrations\n  ZAPIER_WEBHOOK\n  MAILCHIMP_ACTION\n  CONVERTKIT_ACTION\n  STRIPE_ACTION\n}\n\nenum DelayUnit {\n  MINUTES\n  HOURS\n  DAYS\n  WEEKS\n}\n\nmodel WorkflowExecution {\n  id         String   @id @default(cuid())\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n  workflowId String\n\n  // Execution details\n  status      ExecutionStatus @default(RUNNING)\n  startedAt   DateTime        @default(now())\n  completedAt DateTime?\n\n  // Trigger context\n  triggerData     Json // Data that triggered the workflow\n  subscriberEmail String? // If triggered by subscriber action\n\n  // Error handling\n  error      String? @db.Text\n  errorStep  String? // Which step failed\n  retryCount Int     @default(0)\n\n  // Relations\n  workflow Workflow          @relation(fields: [workflowId], references: [id], onDelete: Cascade)\n  stepLogs WorkflowStepLog[]\n\n  @@index([workflowId, status])\n  @@index([status, createdAt])\n  @@index([subscriberEmail])\n  @@map(\"workflow_executions\")\n}\n\nenum ExecutionStatus {\n  PENDING\n  RUNNING\n  WAITING // Waiting for delay/schedule\n  COMPLETED\n  FAILED\n  CANCELLED\n}\n\nmodel WorkflowStepLog {\n  id          String   @id @default(cuid())\n  createdAt   DateTime @default(now())\n  executionId String\n  stepId      String\n\n  // Step execution\n  status      StepExecutionStatus @default(PENDING)\n  startedAt   DateTime?\n  completedAt DateTime?\n\n  // Step data\n  input  Json?\n  output Json?\n\n  // Error details\n  error String? @db.Text\n\n  // Relations\n  execution WorkflowExecution @relation(fields: [executionId], references: [id], onDelete: Cascade)\n  step      WorkflowStep      @relation(fields: [stepId], references: [id], onDelete: Cascade)\n\n  @@index([executionId, stepId])\n  @@map(\"workflow_step_logs\")\n}\n\nenum StepExecutionStatus {\n  PENDING\n  RUNNING\n  COMPLETED\n  FAILED\n  SKIPPED\n}\n\n// ============================================\n// USER ONBOARDING\n// ============================================\n\nmodel UserOnboarding {\n  id        String   @id @default(cuid())\n  userId    String   @unique\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Progress tracking\n  completedSteps    String[]\n  currentStep       String?\n  skipped           Boolean   @default(false)\n  completedAt       DateTime?\n  tourCompleted     Boolean   @default(false)\n  checklistProgress Json      @default(\"{}\")\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@map(\"user_onboarding\")\n}\n\n// ============================================\n// CONVERSION FUNNEL SYSTEM\n// ============================================\n\nmodel Funnel {\n  id        String   @id @default(cuid())\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n  userId    String\n\n  // Funnel details\n  name        String\n  description String? @db.Text\n  slug        String  @unique\n\n  // Goal tracking\n  goalType       FunnelGoalType\n  goalValue      String? // e.g., product ID, course ID, etc.\n  conversionGoal String // \"purchase\", \"signup\", \"download\", etc.\n\n  // Styling and branding\n  theme       Json?\n  brandColors Json?\n  customCss   String? @db.Text\n\n  // SEO\n  metaTitle       String?\n  metaDescription String?\n  ogImage         String?\n\n  // Settings\n  trackingEnabled Boolean @default(true)\n  exitRedirect    String? // Where to redirect after completion\n\n  // Analytics\n  totalVisits      Int      @default(0)\n  totalConversions Int      @default(0)\n  conversionRate   Decimal? @db.Decimal(5, 2)\n\n  // Status\n  status      FunnelStatus @default(DRAFT)\n  publishedAt DateTime?\n\n  // Relations\n  user        User               @relation(fields: [userId], references: [id], onDelete: Cascade)\n  steps       FunnelStep[]\n  visits      FunnelVisit[]\n  conversions FunnelConversion[]\n\n  @@index([userId, status])\n  @@index([slug])\n  @@map(\"funnels\")\n}\n\nenum FunnelGoalType {\n  LEAD_CAPTURE\n  PRODUCT_SALE\n  COURSE_ENROLLMENT\n  BOOKING\n  CUSTOM\n}\n\nenum FunnelStatus {\n  DRAFT\n  ACTIVE\n  PAUSED\n  ARCHIVED\n}\n\nmodel FunnelStep {\n  id        String   @id @default(cuid())\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n  funnelId  String\n\n  // Step details\n  name  String\n  slug  String // URL path segment\n  type  FunnelStepType\n  order Int\n\n  // Page content\n  headline    String?\n  subheadline String?\n  content     String? @db.Text\n\n  // Page-specific data\n  pageData Json? // Flexible storage for different step types\n\n  // Media\n  backgroundImage String?\n  videoUrl        String?\n\n  // Form/CTA configuration\n  ctaText    String?\n  ctaUrl     String?\n  formConfig Json? // For lead capture forms\n\n  // Split testing\n  isVariant    Boolean @default(false)\n  variantOf    String? // ID of parent step\n  trafficSplit Int     @default(50)\n\n  // Analytics\n  views       Int      @default(0)\n  completions Int      @default(0)\n  dropoffRate Decimal? @db.Decimal(5, 2)\n\n  // Conditional logic\n  rules Json? // For conditional branching\n\n  // Relations\n  funnel         Funnel               @relation(fields: [funnelId], references: [id], onDelete: Cascade)\n  stepProgresses FunnelStepProgress[]\n\n  @@unique([funnelId, slug])\n  @@index([funnelId, order])\n  @@map(\"funnel_steps\")\n}\n\nenum FunnelStepType {\n  LANDING_PAGE // Initial landing page\n  LEAD_CAPTURE // Email/info capture\n  SALES_PAGE // Product/service presentation\n  ORDER_FORM // Checkout/payment\n  UPSELL // Additional offer\n  DOWNSELL // Alternative offer\n  THANK_YOU // Confirmation/success\n  VIDEO_SALES // Video-based sales page\n  WEBINAR_REG // Webinar registration\n  SURVEY // Information gathering\n  CUSTOM // Custom step type\n}\n\nmodel FunnelVisit {\n  id        String   @id @default(cuid())\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n  funnelId  String\n\n  // Visitor tracking\n  visitorId String // Unique ID for this visitor session\n  email     String? // Captured email if available\n  name      String?\n\n  // Entry point\n  entryStepId String\n  entryUrl    String?\n  referrer    String?\n\n  // Current progress\n  currentStepId  String?\n  lastStepId     String?\n  completedSteps String[]\n\n  // Session details\n  ipAddress String?\n  userAgent String?\n  device    String?\n  browser   String?\n  os        String?\n  country   String?\n  city      String?\n\n  // UTM tracking\n  utmSource   String?\n  utmMedium   String?\n  utmCampaign String?\n  utmTerm     String?\n  utmContent  String?\n\n  // Engagement\n  totalTimeSpent Int      @default(0) // in seconds\n  lastActivityAt DateTime @default(now())\n\n  // Conversion\n  converted       Boolean   @default(false)\n  convertedAt     DateTime?\n  conversionValue Decimal?  @db.Decimal(10, 2)\n\n  // Relations\n  funnel       Funnel               @relation(fields: [funnelId], references: [id], onDelete: Cascade)\n  stepProgress FunnelStepProgress[]\n\n  @@index([funnelId, visitorId])\n  @@index([funnelId, converted])\n  @@index([email])\n  @@map(\"funnel_visits\")\n}\n\nmodel FunnelStepProgress {\n  id        String   @id @default(cuid())\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n  visitId   String\n  stepId    String\n\n  // Progress tracking\n  status      FunnelStepStatus @default(VIEWED)\n  enteredAt   DateTime         @default(now())\n  completedAt DateTime?\n  timeSpent   Int              @default(0) // in seconds\n\n  // Form data (if applicable)\n  formData Json?\n\n  // Interaction tracking\n  scrollDepth  Int? // Percentage\n  ctaClicked   Boolean @default(false)\n  videoWatched Int? // Percentage\n  interactions Json? // Other tracked interactions\n\n  // Relations\n  visit FunnelVisit @relation(fields: [visitId], references: [id], onDelete: Cascade)\n  step  FunnelStep  @relation(fields: [stepId], references: [id], onDelete: Cascade)\n\n  @@unique([visitId, stepId])\n  @@index([stepId, status])\n  @@map(\"funnel_step_progress\")\n}\n\nenum FunnelStepStatus {\n  VIEWED // User viewed the step\n  ENGAGED // User interacted (scroll, video, etc.)\n  COMPLETED // User completed step action\n  ABANDONED // User left without completing\n  CONVERTED // Led to goal completion\n}\n\nmodel FunnelConversion {\n  id        String   @id @default(cuid())\n  createdAt DateTime @default(now())\n  funnelId  String\n  visitId   String\n\n  // Conversion details\n  conversionType  String // Type of conversion achieved\n  conversionValue Decimal? @db.Decimal(10, 2)\n  currency        String   @default(\"USD\")\n\n  // Attribution\n  entrySource   String?\n  entryMedium   String?\n  entryCampaign String?\n\n  // Customer info\n  email    String\n  name     String?\n  metadata Json?\n\n  // External references\n  orderId   String?\n  productId String?\n  courseId  String?\n\n  // Relations\n  funnel Funnel @relation(fields: [funnelId], references: [id], onDelete: Cascade)\n\n  @@index([funnelId, createdAt])\n  @@index([email])\n  @@map(\"funnel_conversions\")\n}\n\n// ============================================\n// ENHANCEMENT FEATURES (5 New Features)\n// ============================================\n\n// 1. Template Customization Studio\nmodel TemplateCustomization {\n  id         String  @id @default(cuid())\n  templateId String\n  pageId     String?\n  userId     String\n\n  customizations Json    @default(\"{}\")\n  previewData    Json?\n  saved          Boolean @default(false)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  template PageTemplate? @relation(fields: [templateId], references: [id], onDelete: Cascade)\n  page     Page?         @relation(fields: [pageId], references: [id], onDelete: Cascade)\n  user     User          @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([templateId])\n  @@index([userId])\n  @@index([pageId])\n  @@map(\"template_customizations\")\n}\n\n// 2. SEO Performance Tracking\nmodel SEOPerformance {\n  id     String   @id @default(cuid())\n  pageId String\n  userId String\n  date   DateTime\n\n  score    Int\n  errors   Int   @default(0)\n  warnings Int   @default(0)\n  info     Int   @default(0)\n  issues   Json?\n\n  searchRanking  Int?\n  organicTraffic Int      @default(0)\n  impressions    Int      @default(0)\n  clicks         Int      @default(0)\n  ctr            Decimal? @db.Decimal(5, 2)\n\n  createdAt DateTime @default(now())\n\n  page Page @relation(fields: [pageId], references: [id], onDelete: Cascade)\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([pageId, date])\n  @@index([userId])\n  @@index([date])\n  @@map(\"seo_performance\")\n}\n\n// 3. Content Optimization Suggestions\nmodel ContentOptimization {\n  id      String  @id @default(cuid())\n  pageId  String\n  blockId String?\n  userId  String\n\n  suggestionType String\n  field          String\n  currentValue   String?\n  suggestedValue String\n  reason         String?\n  priority       String // high, medium, low\n  impactScore    Int?\n\n  applied   Boolean   @default(false)\n  appliedAt DateTime?\n\n  createdAt DateTime @default(now())\n\n  page  Page   @relation(fields: [pageId], references: [id], onDelete: Cascade)\n  block Block? @relation(fields: [blockId], references: [id], onDelete: SetNull)\n  user  User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([pageId])\n  @@index([userId])\n  @@index([applied])\n  @@map(\"content_optimizations\")\n}\n\n// 4. Template Performance Analytics\nmodel TemplatePerformance {\n  id         String   @id @default(cuid())\n  templateId String\n  pageId     String\n  userId     String\n  date       DateTime\n\n  views          Int      @default(0)\n  clicks         Int      @default(0)\n  conversions    Int      @default(0)\n  conversionRate Decimal? @db.Decimal(5, 2)\n  engagementTime Int?\n  bounceRate     Decimal? @db.Decimal(5, 2)\n  revenue        Decimal  @default(0) @db.Decimal(10, 2)\n\n  createdAt DateTime @default(now())\n\n  template PageTemplate @relation(fields: [templateId], references: [id], onDelete: Cascade)\n  page     Page         @relation(fields: [pageId], references: [id], onDelete: Cascade)\n  user     User         @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([templateId, pageId, date])\n  @@index([templateId])\n  @@index([userId])\n  @@map(\"template_performance\")\n}\n\n// 5. A/B Test Experiments\nmodel ABTestExperiment {\n  id     String @id @default(cuid())\n  pageId String\n  userId String\n\n  name         String\n  description  String?\n  templateAId  String\n  templateBId  String\n  status       String  @default(\"draft\") // draft, running, completed, paused\n  trafficSplit Int     @default(50) // percentage for template A\n\n  startDate        DateTime?\n  endDate          DateTime?\n  winnerTemplateId String?\n  results          Json?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  page           Page          @relation(fields: [pageId], references: [id], onDelete: Cascade)\n  user           User          @relation(fields: [userId], references: [id], onDelete: Cascade)\n  templateA      PageTemplate  @relation(\"TemplateA\", fields: [templateAId], references: [id])\n  templateB      PageTemplate  @relation(\"TemplateB\", fields: [templateBId], references: [id])\n  winnerTemplate PageTemplate? @relation(\"WinnerTemplate\", fields: [winnerTemplateId], references: [id])\n\n  @@index([pageId])\n  @@index([userId])\n  @@index([status])\n  @@map(\"ab_test_experiments\")\n}\n\n// 6. Template Marketplace (Revenue Sharing)\nmodel TemplatePurchase {\n  id         String @id @default(cuid())\n  templateId String\n  buyerId    String\n  sellerId   String\n\n  price          Decimal @db.Decimal(10, 2)\n  currency       String  @default(\"USD\")\n  commission     Decimal @db.Decimal(10, 2)\n  platformFee    Decimal @db.Decimal(10, 2)\n  sellerEarnings Decimal @db.Decimal(10, 2)\n  paymentStatus  String  @default(\"pending\") // pending, completed, failed, refunded\n\n  createdAt DateTime @default(now())\n\n  template PageTemplate @relation(fields: [templateId], references: [id], onDelete: Cascade)\n  buyer    User         @relation(\"TemplateBuyer\", fields: [buyerId], references: [id], onDelete: Cascade)\n  seller   User         @relation(\"TemplateSeller\", fields: [sellerId], references: [id], onDelete: Cascade)\n\n  @@index([templateId])\n  @@index([buyerId])\n  @@index([sellerId])\n  @@map(\"template_purchases\")\n}\n\nmodel TemplateReview {\n  id         String @id @default(cuid())\n  templateId String\n  userId     String\n\n  rating Int // 1-5\n  review String? @db.Text\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  template PageTemplate @relation(fields: [templateId], references: [id], onDelete: Cascade)\n  user     User         @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([templateId, userId])\n  @@index([templateId])\n  @@index([rating])\n  @@map(\"template_reviews\")\n}\n\nmodel TemplateCreatorProfile {\n  id     String @id @default(cuid())\n  userId String @unique\n\n  displayName String?\n  bio         String? @db.Text\n  avatarUrl   String?\n\n  totalTemplates Int      @default(0)\n  totalSales     Int      @default(0)\n  totalRevenue   Decimal  @default(0) @db.Decimal(10, 2)\n  averageRating  Decimal? @db.Decimal(3, 2)\n  verified       Boolean  @default(false)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@map(\"template_creator_profiles\")\n}\n"
}

